bug.fixed:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *big = malloc(10000000 * sizeof(int));
    if (big == NULL) {
        printf("Not enough memory\n");
        return 1;
    }
    big[0] = 1;
    printf("%d\n", big[0]);
    free(big);
    return 0;
}

